(()=>{const q=s=>document.querySelector(s),qa=s=>Array.from(document.querySelectorAll(s)),check=(name,ok)=>{flowChecks.push({name,pass:!!ok});if(!ok)throw Error(name);};try{
q('dialog').close();qa('[data-nav]').find(b=>b.dataset.nav==='segmentos').click();q('#prepare-campaign').click();check('Audience shows eligible plus exclusions and review guard',!!q('[data-campaign-person]')&&q('dialog').textContent.includes('Reunião já marcada')&&q('dialog').textContent.includes('Bloqueio de contato')&&q('#campaign-next').disabled);
const extra=qa('[data-campaign-person]').find(e=>e.dataset.campaignPerson===flowDealId);if(extra)extra.click();
check('Manual deselection changes reviewed public without including blocked lead',!designState().campaign.selected.includes(flowDealId)&&!designState().campaign.selected.includes('d6'));
q('#campaign-audience-reviewed').click();q('#campaign-next').click();q('#campaign-text').value='Olá, {contato}. Podemos combinar uma conversa sobre o Raio X da {empresa}? Exemplo fictício.';q('#campaign-text').dispatchEvent(new Event('input',{bubbles:true}));check('Text approval required before queue preview',q('#campaign-preview').disabled);
q('#campaign-text-approved').click();q('#campaign-text').value+=' Obrigado.';q('#campaign-text').dispatchEvent(new Event('input',{bubbles:true}));check('Editing text invalidates prior approval',!q('#campaign-text-approved').checked&&q('#campaign-preview').disabled&&!designState().campaign.approved);
q('#campaign-text-approved').click();q('#campaign-preview').click();const state=designState();check('Queue preview uses reviewed recipient and personalized approved text',state.campaign.queue.length===1&&state.campaign.queue[0].deal==='d3'&&state.campaign.queue[0].text.includes('Clara Exemplo')&&state.campaign.queue[0].text.includes('Vale Verde Serviços'));
check('Queue is explicitly not operational and no send control',q('dialog').textContent.includes('não enfileirada')&&!qa('dialog button').some(b=>/^enviar|^disparar|^agendar envio/i.test(b.textContent.trim()))&&state.externalWrites===0);
check('Page and open dialog fit viewport',document.documentElement.scrollWidth<=innerWidth&&q('dialog').scrollWidth<=q('dialog').clientWidth);
return {passed:true,phase:4,total:flowChecks.length,checks:flowChecks,viewport:innerWidth};}catch(e){return {passed:false,error:String(e),checks:flowChecks};}})()
